NAME = 'GerAlbrecht: German Albrecht Neues Testament und Psalmen'
BOOK = 'I Timothy'

CHAPTERS = {
    1: {
        1: 'Paulus, von Gott, unserem Retter, und von Christus Jesus, der unsere Hoffnung ist, zum Apostel Christi Jesu bestellt,',
        2: 'entbietet seinem echten Glaubenssohn Timotheus seinen Gruß. Gnade, Barmherzigkeit und Friede sei mit dir von Gott dem Vater und dem Herrn Christus Jesus!',
        3: 'Wie ich dich einst bei meiner Abreise nach Mazedonien gebeten habe, in Ephesus zu bleiben, (so ermahne ich dich nun), gewissen Leuten (dort) einzuschärfen, nicht anderes (als die gesunde Lehre) zu verkündigen',
        4: 'und sich nicht mit Fabeln und endlosen Geschlechterreihen zu befassen. Das gibt nur Anlaß zu allen möglichen Streitfragen und hindert die Wirksamkeit eines Haushalters Gottes, die den Glauben fördern soll.',
        5: 'Und was ist das Ziel der rechten Unterweisung? Liebe, die aus reinem Herzen fließt und aus einem guten Gewissen und ungeheucheltem Glauben.',
        6: 'Davon sind manche abgeirrt und haben sich leerem Geschwätz zugewandt.',
        7: 'Sie wollen Gesetzeslehrer sein und verstehen selbst nicht recht, was sie reden und behaupten.',
        8: 'Nun wissen wir, daß das Gesetz heilsam ist, wenn ein Lehrer (im Unterricht) den rechten Gebrauch davon macht.',
        9: 'Dann muß er aber die Erkenntnis haben, daß das Gesetz nicht für den Gerechten da ist, sondern für Frevler und Ungehorsame, für Gottlose und Sünder, für Unheilige und Ruchlose, für solche, die sich an Vater und Mutter vergreifen, für Mörder,',
        10: 'Hurer, Knabenschänder, Seelenverkäufer, Lügner, Meineidige und alle, die sonst noch der gesunden Lehrer zuwiderhandeln.',
        11: 'Diese Erkenntnis steht im Einklang mit der Frohen Botschaft, wodurch die Herrlichkeit des seligen Gottes kundgemacht wird, und womit ich betraut worden bin.',
        12: 'Unserem Herrn Christus Jesus, der mir Kraft verliehen hat, schulde ich Dank. Denn er hat mich für treu erachtet und zu seinem Dienst bestellt,',
        13: 'obwohl ich (ihn) früher gelästert und (seine Jünger) verfolgt und mißhandelt habe. Doch mir ist Erbarmen widerfahren; denn ich habe in Unwissenheit gehandelt, weil ich ungläubig war.',
        14: 'Und die Gnade unseres Herrn hat sich überschwenglich reich (an mir) bewiesen: sie hat in mir jenen Glauben und jene Liebe erweckt, die sich in Christus Jesus finden.',
        15: 'Es ist ein wahres Wort und allgemeiner Anerkennung wert: "Christus Jesus ist in die Welt gekommen, um Sünder zu erretten." Ich bin der größte unter ihnen.',
        16: 'Aber gerade deshalb ist mir Erbarmen widerfahren, weil Christus Jesus an mir, dem größten Sünder, den ganzen Reichtum seiner Langmut offenbaren und ein Beispiel davon geben wollte, was für Menschen durch den Glauben an ihn zum ewigen Leben kommen sollen.',
        17: 'Ihm aber, dem König des Weltalls, dem unvergänglichen, unsichtbaren, alleinigen Gott, sei Ehre und Preis in alle Ewigkeit! Amen.',
        18: 'Im Blick auf die Weissagungen, die früher über dich ergangen sind, ermahne ich dich herzlich, mein Sohn Timotheus: sei ihrer eingedenk und kämpfe so den herrlichen Kampf;',
        19: 'halte fest am Glauben und erhalte dein Gewissen rein! Auf dessen warnende Stimme haben einige nicht hören wollen, und darum hat ihr Glauben Schiffbruch gelitten.',
        20: 'Zu diesen Leuten gehören Hymenäus und Alexander, die ich dem Satan übergeben habe, damit ihnen unter seiner Züchtigung das Lästern vergehe.',
    },
    2: {
        1: 'Ich verordne nun vor allem: Es sollen Bitten, Gebete, Fürbitten und Danksagungen dargebracht werden für alle Menschen,',
        2: '(besonders) für die Könige und alle (anderen) Machthaber, damit wir ein ruhiges und stilles Leben führen können in aller Gottseligkeit und Ehrbarkeit.',
        3: 'Solches (Gebet) geziemt sich, und es gefällt (auch) Gott, unserem Retter, wohl.',
        4: 'Er will ja, daß alle Menschen errettet werden und zur Erkenntnis der Wahrheit kommen.',
        5: 'Denn es gibt (für alle Menschen und Völker) nur einen Gott, und es gibt auch nur einen Mittler zwischen Gott und Menschen: das ist der Mensch Christus Jesus,',
        6: 'der sich für alle zum Lösegeld dahingegeben hat. Dies sollte zu der (von Gott) bestimmten Zeit bezeugt werden.',
        7: 'Dazu bin ich — das ist die Wahrheit und keine Lüge — zum Herold und Apostel bestellt worden, um die Heiden den Glauben und die Wahrheit zu lehren.',
        8: 'Ich bestimme nun: die Männer sollen an jedem (gottesdienstlichen) Versammlungsort die Gebete sprechen; dabei sollen sie heilige Hände (zu Gott) erheben und sich von Zorn und Streitsucht fernhalten.',
        9: 'Auch die Frauen sollen beim Gebet zugegen sein[3]. Aber sie sollen in würdiger Tracht erscheinen, sich sittsam und bescheiden benehmen und nicht prunken mit künstlichen Haarflechten, Goldgeschmeide, Perlenschmuck oder kostbarer Kleidung.',
        10: 'Sie sollen sich vielmehr durch den Schmuck guter Werke auszeichnen; denn das ziemt sich für Frauen, die in Gottesfurcht wandeln wollen.',
        11: 'Die Frau soll (beim Gottesdienst) in aller Unterordnung still zuhören.',
        12: 'Ich erlaube keiner Frau, (öffentlich) zu lehren oder sich über den Mann zu stellen; sondern sie soll sich still verhalten.',
        13: 'Denn Adam ist zuerst geschaffen worden, danach Eva.',
        14: 'Auch hat sich Adam nicht verführen lassen, sondern das Weib ist verführt worden und in Übertretung gefallen.',
        15: 'Die Frauen sollen aber (trotz Evas Übertretung) das Heil erlangen, wenn sie (in Erfüllung ihres Mutterberufs) Kinder gebären (und erziehen); nur müssen sie dabei auch mit aller Sittsamkeit in Glauben, Liebe und Heiligung beharren.',
    },
    3: {
        1: 'Es ist ein wahres Wort: "Wer seine Hand nach dem Bischofsamt ausstreckt, der begehrt ein köstliches Arbeitsfeld."',
        2: 'Ein Bischof muß nun ohne Tadel sein, eines Weibes Mann, ernst, besonnen, gesetzt, gastfrei, lehrtüchtig.',
        3: 'Er darf kein Trinker und kein Händelsucher sein; er muß vielmehr sanftmütig sein und allem Streit aus dem Weg gehen. Er darf nicht geldgierig sein.',
        4: 'Er muß seinem eigenen Haus gut vorstehen und seine Kinder zum Gehorsam und zu einem ehrbaren Lebenswandel anhalten.',
        5: 'Denn wer sein eigenes Haus nicht in Ordnung halten kann, wie ist der fähig, für die Gemeinde Gottes zu sorgen?',
        6: 'Kein Neugetaufter (soll sofort Bischof werden, damit er nicht, von Stolz verblendet, einem ähnlichen Strafgericht verfalle, wie es den Teufel getroffen hat.',
        7: 'Der Bischof muß sich auch eines guten Rufs erfreuen bei denen, die außerhalb (der Kirche) stehen, damit er nicht dem Teufel Anlaß gebe, ihn zu verleumden und in seine Schlinge zu ziehen.',
        8: 'Die Diakonen sollen gleichfalls achtbare Männer sein. Sie müssen sich hüten vor Doppelzüngigkeit, übermäßigem Weingenuß und schmutziger Gewinnsucht.',
        9: 'Denn sie sollen das Geheimnis des Glaubens in einem reinen Gewissen bewahren.',
        10: 'Auch sie sollen zunächst (auf ihre Würdigkeit) geprüft und erst dann zum Dienst zugelassen werden, wenn keine Beschwerde gegen sie erhoben worden ist.',
        11: 'Auch die Diakonissen müssen achtbar sein. Sie dürfen nicht klatschen und verleumden, sondern sie müssen ernst sein und in jeder Hinsicht zuverlässig.',
        12: 'Die Diakonen sollen jeder eines Weibes Mann sein und ihre Kinder und Häuser gut in Ordnung halten.',
        13: 'Denn solche Diakonen, die ihr Amt gut ausrichten, gewinnen eine ehrenvolle Stellung und können im Vertrauen auf Christus Jesus mit großer Zuversichtlichkeit (in der Gemeinde) auftreten.',
        14: 'Dies schreibe ich dir, obwohl ich hoffe, recht bald zu dir zu kommen.',
        15: 'Sollte sich aber meine Ankunft verzögern, so weißt du nun, wie du dich zu verhalten hast in dem Haus Gottes, das da ist die Kirche des lebendigen Gottes, die Säule und Grundfeste der Wahrheit.',
        16: "Und wahrlich, etwas Großes ist's um das Geheimnis der Gottseligkeit! Der offenbart ist im Fleisch, der ist gerechtfertigt worden durch den Geist: Er ist erschienen seinen Boten, gepredigt unter den Völkern, geglaubt in der Welt, aufgenommen in die Herrlichkeit.",
    },
    4: {
        1: 'Der Geist verkündigt ganz ausdrücklich, daß in späteren Zeiten manche vom Glauben abfallen werden, weil sie irreführenden Geistern folgen und Teufelslehren,',
        2: 'die von heuchlerischen Lügnern ausgehen: Von Menschen, die in ihrem Gewissen (gleich Verbrechern) ein Brandmal ihrer Schuld tragen.',
        3: 'Diese Leute verbieten die Ehe und den Genuß von Speisen, die doch Gott geschaffen hat, damit sie von den Gläubigen, die die Wahrheit erkannt haben, mit Danksagung genossen werden.',
        4: "Denn alles, was Gott geschaffen hat, ist gut; und (darum) braucht man auch kein Nahrungsmittel (als böse) zu verwerfen, wenn man's mit Danksagung genießt.",
        5: 'Es wird ja geheiligt durch Gottes Wort, das in dem Tischgebet zum Ausdruck kommt.',
        6: 'Wenn du so die Brüder unterweist, wirst du ein trefflicher Diener Christi Jesu sein; denn dann nährst du dich mit den Worten des Glaubens und der heilsamen Lehre, der du bisher gefolgt bist.',
        7: 'Jene Fabeleien aber, die mit dem Heiligen nichts zu tun haben, und die nur leeres Geschwätz sind, die laß beiseite! Hingegen übe dich, in der Frömmigkeit zu wachsen!',
        8: 'Denn die leibliche Übung bringt wenig Nutzen. die Frömmigkeit aber ist zu allem nütze, denn sie hat eine Verheißung für dieses Leben und das zukünftige.',
        9: 'Das ist ein wahres Wort und allgemeiner Anerkennung wert.',
        10: 'Wir nehmen ja deshalb Mühe und Schande auf uns, weil wir auf den lebendigen Gott vertrauen: der ist der Retter aller Menschen und ganz besonders der Gläubigen.',
        11: 'Dies schärfe ein und lehre!',
        12: 'Damit niemand deiner Jugend wegen gering von dir denke, so sei in Wort und Wandel, in Liebe, Glauben und Sittenreinheit den Gläubigen ein Vorbild!',
        13: 'Bis zu meiner Ankunft sorge dafür, daß die heiligen Schriften vorgelesen werden, und daß die Gemeinde Ermahnung und Belehrung empfange!',
        14: 'Versäume nicht, die Gnadengabe zu betätigen, die in dir wohnt, und die dir nach vorausgegangener Weissagung unter Handauflegung der Ältestenschaft (von mir) zuteil geworden ist.',
        15: 'Dies laß deine Sorge sein; dem gibt dich hin, damit alle deutlich sehen, wie du (im geistlichen Leben) fortschreitest!',
        16: 'Achte beharrlich auf dein Verhalten und auf die Lehre, (die du vorträgst)! Tust du das, so wirst du dich und deine Hörer zum Heil führen.',
    },
    5: {
        1: 'Auf einen älteren Mann schlage nicht (mit harten Worten) los, sondern sprich ihm zu, als wäre er dein Vater; jüngere Männer behandle wie Brüder,',
        2: 'ältere Frauen wie Mütter, jüngere wie Schwestern, jedoch mit aller Sittsamkeit!',
        3: 'Unterstütze solche Witwen, die wirklich hilfsbedürftig sind!',
        4: 'Hat aber eine Witwe Kinder oder Enkel, so sollen diese zunächst lernen, ihren Angehörigen Liebe zu beweisen und ihren Müttern und Großmüttern die empfangenen Wohltaten zu vergelten. Denn das ist Gott wohlgefällig.',
        5: 'Eine wirklich hilfsbedürftige Witwe, die ganz allein steht, die setzt ihre Hoffnung auf Gott und fleht und betet unablässig Tag und Nacht.',
        6: 'Eine Witwe aber, die ein ausschweifendes Leben führt, ist bei lebendigem Leib tot.',
        7: 'Dies schärfe ihnen ein, damit man ihnen nicht vorwerfen könne!',
        8: 'Sorgt ein Hausvater nicht für seine Hausgenossen und namentlich nicht für seine nächsten Verwandten, so hat er den Glauben verleugnet und ist schlimmer als ein Heide.',
        9: 'Eine Witwe darf nur dann in das Witwenverzeichnis aufgenommen werden, wenn sie mindestens sechzig Jahre alt ist. Sie muß eines Mannes Ehefrau gewesen sein',
        10: 'und sich durch gute Werke ein ehrenvolles Zeugnis erworben haben. Dahin gehört, daß sie Kinder großgezogen, Gastfreundschaft geübt, den Heiligen die Füße gewaschen, den Bedrängten geholfen, kurz, sich an allen möglichen Liebeswerken beteiligt hat.',
        11: 'Jüngere Witwen weise ab! Denn wenn sie im Widerspruch mit dem Dienst Christi von Liebeslust gereizt werden, so wollen sie (wieder) heiraten.',
        12: 'Damit setzen sie sich dann aber dem Vorwurf aus, daß sie ihr früher gegebenes Wort gebrochen haben.',
        13: 'Zugleich gewöhnen sie sich daran, in trägem Nichtstun von Haus zu Haus zu laufen; und nicht nur das, sondern bei ihrer Geschwätzigkeit und Neugier führen sie auch ungehörige Reden.',
        14: "Darum halte ich's für ratsam, daß jüngere Witwen (wieder) heiraten, Kinder gebären und das Hauswesen besorgen, so daß sie den Widersachern keinen Anlaß zu übler Nachrede geben.",
        15: 'Denn manchen haben sich schon vom rechten Weg abgewandt und sind dem Satan nachgefolgt.',
        16: 'Hat irgendein weibliches Gemeindeglied Witwen (zu seiner Pflege und Handreichung), so soll es auch für sie sorgen. In solchem Fall darf die Gemeinde nicht beschwert werden, damit sie den wirklich bedürftigen Witwen ausreichend helfen könne.',
        17: "Die Ältesten, die als Vorsteher Tüchtiges leisten, ganz besonders solche, die sich's bei der Predigt und Belehrung (der Gemeinde) sauer werden lassen, die sollen durch eine doppelte Gabe geehrt werden.",
        18: 'Denn die Schrift sagt: Du sollst einem dreschenden Ochsen nicht das Maul verbinden, und: "Der Arbeiter ist seines Lohnes wert."',
        19: 'Gegen einen Ältesten nimm keine Klage an, wenn nicht zwei oder drei Zeugen vorhanden sind.',
        20: 'Die (Ältesten), deren Schuld erwiesen ist, weise in Gegenwart aller zurecht, damit auch die anderen gewarnt werden!',
        21: 'Vor Gott, dem Herrn Jesus Christus und den auserwählten Engeln ermahne ich dich ernstlich: führe diese Anweisungen ohne Vorurteil aus und tue nichts nach Gunst!',
        22: 'Lege niemand übereilt die Hände auf und mache dich nicht an den Sünden anderer mitschuldig! Halte dich rein!',
        23: 'Trinke nicht mehr ausschließlich Wasser, sondern wegen deines Magens und deiner häufigen Kränklichkeit genieße etwas Wein!',
        24: 'Bei manchen Menschen liegen die Sünden so klar zutage, daß sie ihnen wie Vorboten auf dem Weg zum Gericht voraneilen; bei anderen treten sie erst später ans Licht.',
        25: "Ebenso ist's auch mit den guten Werken: einige sind ganz offenkundig; doch auch solche, mit denen sich's anders verhält, können nicht verborgen bleiben.",
    },
    6: {
        1: 'Alle, die als Sklaven unter einem Joch schmachten, sollen ihre Herren in jeder Weise ehren, damit der Name Gottes und die Lehre nicht verlästert werden.',
        2: 'Die Sklaven aber, die Gläubige zu Herren haben, sollen deshalb, weil die Herren (christliche) Brüder sind, nicht geringere Ehrfurcht vor ihnen haben. Im Gegenteil, sie sollen ihnen um so williger dienen; denn sie haben es mit Gläubigen und Freunden zu tun, die ihre Wohltäter heißen wollen. Dies lehre und schärfe ein!',
        3: 'Wer anders lehrt und sich nicht hält an die gesunden Aussprüche unseres Herrn Jesus Christus und an die Lehre, die der Frömmigkeit entspricht,',
        4: 'der ist (von Hochmut) verblendet und hat kein rechtes Verständnis. Er krankt vielmehr an der Sucht, sich mit (müßigen) Streitfragen und Wortgezänk zu befassen. Daraus entstehen nur Neid, Hader, Schmähungen, aller mögliche schlimme Argwohn',
        5: 'und fortwährende Reibereien. So sieht es aus bei Menschen, deren ganze Denkart verderbt ist, und die den Sinn für die Wahrheit verloren haben, so daß sie die Frömmigkeit nur als ein Mittel zum Gelderwerb betrachten.',
        6: 'Allerdings liegen reiche Schätze in der Frömmigkeit, wenn sie mit Genügsamkeit verbunden ist.',
        7: 'Wir haben ja nichts mit in die Welt gebracht, und wir können auch nichts mit hinausnehmen.',
        8: 'Haben wir Nahrung und Kleidung, so ist das für uns genug.',
        9: 'Die nach Reichtum trachten, fallen in Versuchung und Schlingen und viel unvernünftige und schädliche Begierden, die die Menschen in den Abgrund des Verderbens stürzen.',
        10: 'Denn die Geldgier ist eine Wurzel aller Übel. Gar manche, die ihre Hand nach dem Geld ausgestreckt haben, sind von dem Weg des Glaubens abgeirrt und haben sich selbst in bitteres Leid gebracht.',
        11: 'Du, Mann Gottes, fliehe dieses Laster! Trachte vielmehr nach der Gerechtigkeit und Frömmigkeit, nach dem Glauben und der Liebe, nach der Geduld und Sanftmut!',
        12: 'Kämpfe den herrlichen Kampf des Glaubens, erringe das ewige Leben als Siegespreis! Dazu bist du berufen und hast in Gegenwart vieler Zeugen das herrliche Bekenntnis (deines Glaubens) abgelegt.',
        13: 'Vor Gott, der allen Dingen Leben gibt, und vor Christus Jesus, der unter Pontius Pilatus sein herrliches Bekenntnis mit dem Tod besiegelt hat, ermahne ich dich:',
        14: 'Bewahre meine Lehre fleckenlos und unversehrt bis auf die Erscheinung unseres Herrn Jesus Christus!',
        15: 'Die wird uns zur rechten Zeit schauen lassen der selige und alleinige Machthaber, der König der Könige und Herr der Herren — er,',
        16: 'der allein Unsterblichkeit hat, der in einem unzugänglichen Licht wohnt, den kein Mensch gesehen hat noch sehen kann. Ihm sei Ehre und Gewalt in Ewigkeit! Amen.',
        17: 'Die Reichen in dieser Welt warne vor Hochmut! Sie sollen ihre Hoffnung nicht auf den unsicheren Reichtum setzen, sondern auf Gott, der uns alles, was wir nötig haben, in reicher Fülle schenkt.',
        18: 'Sie sollen wohltun, an guten Werken reich werden, freigebig und mildtätig sein',
        19: 'und sich so einen herrlichen Schatz für die Zukunft sammeln, damit sie das wahre Leben erlangen.',
        20: 'O Timotheus, bewahre das dir anvertraute Gut; wende dich ab von dem unreinen, leeren Geschwätz und den Streitsätzen der fälschlich sogenannten Erkenntnis!',
        21: 'Denn manche, die sich mit ihr eingelassen haben, sind vom Glauben abgeirrt. Die Gnade sei mit dir!',
    },
}
